// Construit le résumé quotidien à partir des lignes { titre, prix, lien, note } (Google Sheet ou JSON).
const cfg = $('Config').first().json;
const num = v => {
  const n = parseFloat(String(v == null ? '' : v).replace(/[^\d.,-]/g, '').replace(',', '.'));
  return isNaN(n) ? null : n;
};
const pick = (r, ...keys) => { for (const k of keys) if (r[k] != null && r[k] !== '') return r[k]; return null; };

const rows = $input.all().map(i => i.json).map(r => ({
  titre: String(pick(r, 'titre', 'Titre', 'title') || '').trim(),
  prix: num(pick(r, 'prix', 'Prix', 'price')),
  lien: String(pick(r, 'lien', 'Lien', 'url', 'link') || '').trim(),
  note: num(pick(r, 'note', 'Note', 'rating')),
})).filter(r => r.titre && r.prix != null);

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const today = new Date().toLocaleDateString('fr-FR', { timeZone: 'Europe/Paris', day: '2-digit', month: 'long', year: 'numeric' });
const titre = cfg.titre || 'Veille quotidienne';

if (!rows.length) {
  return [{ json: {
    subject: `${titre} — ${today} : aucune donnée`,
    html: `<p>Aucune ligne exploitable dans la source (${cfg.source === 'sheet' ? 'Google Sheets' : esc(cfg.jsonUrl)}). Vérifiez le nœud Config.</p>`,
    count: 0,
  } }];
}

const prix = rows.map(r => r.prix);
const min = Math.min(...prix), max = Math.max(...prix);
const moy = prix.reduce((a, b) => a + b, 0) / prix.length;
const fmt = n => n.toFixed(2).replace('.', ',') + ' €';
const moinsChers = [...rows].sort((a, b) => a.prix - b.prix).slice(0, 5);
const mieuxNotes = rows.filter(r => r.note != null).sort((a, b) => b.note - a.note).slice(0, 3);

const td = 'padding:6px 10px;border-bottom:1px solid #eee';
const ligne = r => `<tr><td style="${td}">${r.lien ? `<a href="${esc(r.lien)}">${esc(r.titre)}</a>` : esc(r.titre)}</td>` +
  `<td style="${td};text-align:right"><b>${fmt(r.prix)}</b></td>` +
  `<td style="${td};text-align:center">${r.note != null ? r.note.toFixed(1) + ' / 5' : '—'}</td></tr>`;
const table = arr => `<table style="border-collapse:collapse;width:100%;font-size:14px"><thead><tr style="background:#f4f4f5">` +
  `<th style="text-align:left;padding:6px 10px">Produit</th><th style="text-align:right;padding:6px 10px">Prix</th>` +
  `<th style="padding:6px 10px">Note</th></tr></thead><tbody>${arr.map(ligne).join('')}</tbody></table>`;
const tuile = (label, val, bg) => `<td style="padding:8px 14px;background:${bg};border-radius:6px"><b>${label}</b><br>${val}</td><td style="width:8px"></td>`;

const html = `<div style="font-family:Arial,sans-serif;max-width:680px;color:#222">
<h2 style="margin:0 0 4px">${esc(titre)}</h2>
<p style="color:#666;margin:0 0 16px">${today} — ${rows.length} offres analysées</p>
<table style="border-collapse:collapse;margin-bottom:16px"><tr>${tuile('Prix min', fmt(min), '#ecfdf5')}${tuile('Prix moyen', fmt(moy), '#eff6ff')}${tuile('Prix max', fmt(max), '#fef2f2')}</tr></table>
<h3 style="margin:16px 0 6px">Top 5 des moins chers</h3>${table(moinsChers)}
${mieuxNotes.length ? `<h3 style="margin:16px 0 6px">Les mieux notés</h3>${table(mieuxNotes)}` : ''}
<p style="color:#888;font-size:12px;margin-top:20px">Résumé généré automatiquement par n8n (workflow 05 — veille quotidienne).</p>
</div>`;

return [{ json: {
  subject: `${titre} — ${today} : ${rows.length} offres, min ${fmt(min)}`,
  html,
  count: rows.length,
  min, max,
  moyenne: Math.round(moy * 100) / 100,
} }];
